function RedPointMgrComponent:__init()
    ECSComponent.__init(self)
    ---@type RedPointDojo
    self.rootNode = nil                --根
    self.redPointTreeList = {}
    self._RedPointNodeCompare = {}     --红点节点和服务器key的对照
    self._allRedPoints = {}            --所有的服务器红点消息
    self._tiemDown = nil               --红点计时器

    self._goodsMapping = {}            --道具的映射
    self._localBuff = {}               --本地缓存

    self.EventOnAppQuit = Events.AddListener(Constants.EventNames.ONAPPQUIT, Bind(self, self.OnAppQuit))
end

function RedPointMgrComponent:__delete()
    self.rootNode = nil --根
    self.redPointTreeList = nil
    self._RedPointNodeCompare = nil
    self._allRedPoints = nil
    if not isNull(self._tiemDown) then
        CDTimerModule.GetInstance():RemoveCD(self._tiemDown)
        self._tiemDown = nil
    end
    self._goodsMapping = nil            --道具的映射
end

function RedPointMgrComponent:PrintLog(logStr, extLog)
    print(string.format('<color=#CCCC99>[RedPoint] %s</color>', tostring(logStr)), extLog and tostring(extLog) or '')
end

--初始化服务器数据
function RedPointMgrComponent:Initial(jsonData)
    self:InitConfig()
    self:Init()

    -- 服务器-1为不显示  0为显示  大于0为秒数之后显示
    for k, v in pairs(jsonData) do
        if k == "unMallAccmulativePay" and not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id165) then
            -- 未解锁不处理
        elseif self._storeNewProductRef[k] then -- 解锁商品
            if next(v) then
                self:SetNodeNum(Constants.RedPointConst.OverseaStoreNew, 1)
                ---@type OverseaStoreMgr
                local overseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
                overseaStoreMgr:UnlockNewProduct(self._storeNewProductRef[k], v)
            end
        else
            local nodeKey = self:GetRedPointConfigNode(k)
            self:PrintLog(string.format("初始化服务器红点 [ key : %s,  num : %s, node : %s ]", k, tostring(v), checkString(nodeKey)))
            if nodeKey then
                if isNotNull(v) and checkNumber(v) == 0 then
                    self:SetNodeNum(nodeKey, 1)
                else
                    self:SetNodeNum(nodeKey, 0)
                end
            end
            self._allRedPoints[checkString(k)] = checkNumber(v)
        end
    end
    self:HandleRedPoint()
end

--服务器更新红点状态
function RedPointMgrComponent:UpdateRedPointData(jsonData)
    if not jsonData then
        return
    end
    jsonData = checkTable(jsonData)

    -- 服务器-1为不显示  0为显示  大于0为秒数之后显示
    for k, v in pairs(jsonData) do
        if k == "unMallAccmulativePay" and not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id165) then
            -- 未解锁不处理
        elseif k == "unReceivedJobModule" then
            GameUtils.SetRedPointNum(Constants.RedPointConst.MainVeteranAllowance, 1)
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.MainVeteranAllowance)
        elseif self._storeNewTabRef[k] then -- 解锁商城
            self:SetNodeNum(Constants.RedPointConst.OverseaStoreNew, 1)
            ---@type OverseaStoreMgr
            local overseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
            overseaStoreMgr:UnlockNewStore(self._storeNewTabRef[k])
            
        elseif self._storeNewProductRef[k] then -- 解锁商品
            self:SetNodeNum(Constants.RedPointConst.OverseaStoreNew, 1)
            ---@type OverseaStoreMgr
            local overseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
            overseaStoreMgr:UnlockNewProduct(self._storeNewProductRef[k], v)
        else
            local nodeKey = self:GetRedPointConfigNode(k)
            self:PrintLog(string.format("服务器更新红点 [ key : %s, num : %s, node : %s ]", k, tostring(v), checkString(nodeKey)))
            --如果有这个节点配置
            if nodeKey then
                if isNotNull(v) and checkNumber(v) == 0 then
                    self:SetNodeNum(nodeKey, 1)
                    ----------好友部分红点需重新请求
                    --local OpenType = {
                    --    FriendList = 1,--好友列表
                    --    AddFriend = 2,--添加好友
                    --}
                    if checkString(nodeKey) == Constants.RedPointConst.FriendRequest  then
                        Events.Broadcast(Constants.EventNames.FriendInfoChange, 2)
                    elseif checkString(nodeKey) == Constants.RedPointConst.FriendGiftOneClick then
                        Events.Broadcast(Constants.EventNames.FriendInfoChange, 1)
                    end
                    ----------------------------
                else
                    self:SetNodeNum(nodeKey, 0)
                end
            end
            self._allRedPoints[checkString(k)] = checkNumber(v)
        end
    end
end

