--获取服务器的数据
function RedPointMgrComponent:GetServerRedPointData(nodeName)
    local serverkey
    for k, v in pairs(self._RedPointNodeCompare) do 
        if v == nodeName then
            serverkey = k
            break
        end
    end
    return self._allRedPoints[serverkey] or 0
end

--初始化节点
function RedPointMgrComponent:Init()
    self.rootNode = RedPointDojo.New()
    self.rootNode.name = Constants.RedPointConst.Main
    self.rootNode.numChangeCb = function (targetNode)
        local str = string.format('刷新小红点数量 [ key : %s, num : %s ]', tostring(targetNode.name), tostring(targetNode.pointNum))
        self:PrintLog(str)
    end

    for k, v in pairs(self.redPointTreeList) do
        local node = self.rootNode
        --每个分支的根都必须是main
        local nodes = CfUtils.Split(v, ".")
        if nodes[1] ~= node.name then
            printError("red point 配置错误, k:"..k..",v: "..v)
            return
        end

        if #nodes > 1 then
            --从第二个开始依次创建节点
            for i = 2, #nodes do
                if not node.dicChilds[nodes[i]] then
                    node.dicChilds[nodes[i]] = RedPointDojo.New()
                end
                node.dicChilds[nodes[i]].name = node.name.."."..nodes[i]
                node.dicChilds[nodes[i]].parentNode = node
                node = node.dicChilds[nodes[i]]
            end
        end
    end

    self:InitLocalData()
end

--初始化本地记录
function RedPointMgrComponent:InitLocalData()
    self._localBuff = {}
    local str = CfUtils.GetLocalData(REDPOINTKEY, "0")
    if checkString(str) == "0" then
    else
        self._localBuff = table.deserialize(str)
        self:PrintLog("初始化本地红点状态", table.dump(self._localBuff))
    end
end

--退出时写入本地记录
function RedPointMgrComponent:WriteRedPointLocal()
    if self.entity then
        if not self._localBuff then
            self._localBuff = {}
        end
        local str = checkString(table.serialize(self._localBuff))
        CfUtils.WriteLocalData(REDPOINTKEY, str)
    end
end

--[[
    @desc 设置一个节点的红点数，会激活一次回调
    author:{author}
    time:2020-03-16 15:10:43
    --@strNode string 节点的字符串
    --@num int 数量 
    --@isServerUpdate bool 是否是服务器更新 
    @return:
]]
function RedPointMgrComponent:SetNodeNum(strNode, num, isServerUpdate)
    if not strNode then
        return
    end
    if not num then
        num = 0
    end

    local nodes = CfUtils.Split(strNode, ".")
    if #nodes == 1 and nodes[1] ~= Constants.RedPointConst.Main then
        printError("参数错误，strNode："..strNode)
    end

    local node = self.rootNode
    for i = 2, #nodes do
        if not node.dicChilds[nodes[i]] then
            printError("没有该节点 ："..strNode)
            return
        end
        node = node.dicChilds[nodes[i]]
        if i == #nodes then
            node:SetPointNum(num, self:IsNeedLockNode(strNode, isServerUpdate))
        end
    end

    --print("##########strnode: "..strNode.."  num: "..num)
end
function RedPointMgrComponent:GetNodeNum(strNode)
    if not strNode then return end

    local nodes = CfUtils.Split(strNode, ".")
    if #nodes == 1 and nodes[1] ~= Constants.RedPointConst.Main then
        printError("参数错误，strNode："..strNode)
    end

    local node = self.rootNode
    for i = 2, #nodes do
        if not node.dicChilds[nodes[i]] then
            printError("没有该节点 ："..strNode)
            return
        end
        node = node.dicChilds[nodes[i]]
        if i == #nodes then
            return node:GetPointNum()
        end
    end
end

--[[
    @desc: 
    author:{author}
