    --@strNode string 节点的字符串
	--@cb function 回调
    @return:
]]
---@param strNode string
---@param cb fun(node:RedPointDojo):void
function RedPointMgrComponent:SetNodeCallBack(strNode, cb)
    if not strNode then
        return
    end

    local nodes = CfUtils.Split(strNode, ".")
    if #nodes == 1 and nodes[1] ~= Constants.RedPointConst.Main then
        printError("参数错误，strNode："..strNode)
    end
    
    local node = self.rootNode
    for i = 2, #nodes do
        if not node.dicChilds[nodes[i]] then
            printError("没有该节点 ："..strNode)
            return
        end
        node = node.dicChilds[nodes[i]]
        if i == #nodes then
            node.numChangeCb = function()
