--[[
    @desc: 是否需要锁住节点 不会实时刷新数据的界面再收到服务器数据时都要上锁
    author:{author}
    time:2020-05-23 11:01:54
    --@strNode:
	--@isServerUpdate: 
    @return:
]]
function RedPointMgrComponent:IsNeedLockNode(strNode, isServerUpdate)
    if isServerUpdate then
        --邮件
        if strNode == Constants.RedPointConst.Mail then
            local topDialog = UIModule.CurrentScreen:LastDialog()
            if topDialog.Argument.id == Constants.UITypeIds.MailBox then
                return true
            end
        end
    end

    return false
end

--启动红点计时器   !!这个计时器只会使节点变为开启状态
function RedPointMgrComponent:HandleRedPoint()
    if not self._allRedPoints then
        return
    end
    self._tiemDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        for k, v in pairs(self._allRedPoints) do
            v = checkNumber(v)
            if v > 0 then
                self._allRedPoints[k] = v - 1
                --该显示了
                if self._allRedPoints[k] == 0 then
                    local key = self:GetRedPointConfigNode(k) 
                    if key then
                        self:SetNodeNum(key, 1)
                    end
                end
            end
        end
    end, 2592000, false, true)
end

--- 更新活动红点
function RedPointMgrComponent:UpdateActivityRetPoint()
    GameUtils.Request(Interfaces.ActivityHome, {}, function(request, response)
        local data = checkTable(response.data)
        ---@type ActivityMgr
        local ActivityMgr = import('Game.Activity.ActivityMgr'):GetInstance()
        ActivityMgr:UpdateSpecialRed(checkTable(data.activities))
        for i, v in ipairs(checkTable(data.activities)) do
            if checkNumber(v.redDotHint >= 0) then
                self:UpdateRedPointData({unReceivedActivity = 0})
                break
            end
        end
    end)
end

