--更新本地记录
function RedPointMgrComponent:UpdateReadPointLocalKey(localkey, id, isActive)
    localkey = checkNumber(localkey)
    id = checkString(id)
    isActive = (checkNumber(isActive) == 1 and true or false)

    local t
    --物品
    if localkey == Constants.RedPointLocalKey.Goodkey then 
        t = self._localBuff.goods
       if not t then
            self._localBuff.goods = {}
            t = self._localBuff.goods
        end 
    end
    if not t then
        return
    end
    
    if isActive then
        t[id] = 1
    else
        --关闭就删除
        t[id] = nil
    end
    self:PrintLog('更新红点状态', table.dump(self._localBuff))
end

--获取本地该类型所有物品
function RedPointMgrComponent:GetRedPointLocalAllGoods(localkey, goodsType, idAreaType)
    localkey = checkNumber(localkey)
    local t 
    --物品
    if localkey == Constants.RedPointLocalKey.Goodkey then 
        t = self._localBuff.goods
    end

    local _t = {}
    if not t then
        return _t
    end
    goodsType = checkNumber(goodsType)
    idAreaType = checkNumber(idAreaType)
    
    for k, v in pairs(t) do
        local itemType = GoodsUtils.GetIdType(k, idAreaType)
        if itemType == goodsType then
            table.insert(_t, checkString(k))
        end
    end
    return _t
end

--- AddGoodsMappingCard
---启动时增加物品映射卡牌
---@param cardDojo CardDojo
function RedPointMgrComponent:AddGoodsMappingCard(cardDojo)
    local cardConfMgr    = CardConfMgr:GetInstance()
    local cardId         = cardDojo.cardId
    local maxAwakeLv     = cardConfMgr:GetMaxAwakenLevel(cardId)
    local awakeningLevel = checkNumber(cardDojo.awakeningLevel)
    local isMaxLv        = awakeningLevel >= maxAwakeLv
    if isMaxLv then
        return
    end

    --技能升级的消耗
    local consume = cardConfMgr:GetSkillSPLevelUpByReFID(cardId, awakeningLevel + 1)
    if consume and next(consume) ~= nil then
        for k, v in pairs(consume) do
            if checkNumber(v.goodsId) ~= 0 then
                local t = self._goodsMapping[checkString(v.goodsId)]
                if t then
                    --卡牌的分组
                    local cardT = t.card
                    if cardT then
                        cardT[checkString(cardDojo.cardId)] = v.goodsNum
                    else
                        t.card = {}
                        t.card[checkString(cardDojo.cardId)] = v.goodsNum
                    end
                else
                    self._goodsMapping[checkString(v.goodsId)] = {}
                    local _t = self._goodsMapping[checkString(v.goodsId)]
                    _t.card = {}
                    _t.card[checkString(cardDojo.cardId)] = v.goodsNum
                end
            end
        end
    end
end

--- DeleteGoodsMappingCard
---删除掉这个卡技能的对照
---@param cardDojo CardDojo
function RedPointMgrComponent:DeleteGoodsMappingCard(cardDojo)
    local cardConfMgr    = CardConfMgr:GetInstance()
    local cardId         = cardDojo.cardId
    local maxAwakeLv     = cardConfMgr:GetMaxAwakenLevel(cardId)
    local awakeningLevel = checkNumber(cardDojo.awakeningLevel)
    --技能升级的消耗
    local consume        = cardConfMgr:GetSkillSPLevelUpByReFID(cardId, math.min(awakeningLevel, maxAwakeLv))
    if consume and next(consume) ~= nil then
        for k, v in pairs(consume) do
            if checkNumber(v.goodsId) ~= 0 then
                local t = self._goodsMapping[checkString(v.goodsId)]
                if t then
                    if t.card then
                        t.card[checkString(cardId)] = nil
                    end
                end
            end
        end
    end
end

--这里只管点亮小红点
function RedPointMgrComponent:RefreshCardSkillUpNodeWithGood(goodsId, oldNum, NewNum)
    goodsId = checkString(goodsId)
    oldNum = checkNumber(oldNum)
    NewNum = checkNumber(NewNum)
    local t = self._goodsMapping[goodsId]
    if not t then
        return
    end

    --找卡牌的对照
    t = t.card 
    if not t then
        return
    end 

    if next(t) ~= nil then
        for k, v in pairs(t) do
            --到了条件才激活一次
            if checkNumber(v) > oldNum and checkNumber(v) <= NewNum then
                GameUtils.SetRedPointNum(Constants.RedPointConst.StrengthenList, 1)
                return
            end
        end
    end
end

