function RedPointMgrComponent:OnAppQuit()
    self:WriteRedPointLocal()
    Events.RemoveListener(Constants.EventNames.ONAPPQUIT, self.EventOnAppQuit)
end


function RedPointMgrComponent:DumpRedPointNumInfo()
    ---@param redPointDojo RedPointDojo
    local function getFunc(redPointDojo)
        if not redPointDojo then return '' end
        local result = {}
        local redNum = redPointDojo:GetPointNum()
        if redNum > 0 then
            table.insert(result, string.fmt('[%1] %2', redNum, redPointDojo.name))
        end
        for _, subRedPointDojo in pairs(redPointDojo.dicChilds) do
            table.insert(result, getFunc(subRedPointDojo))
        end
        return #result > 0 and table.concat(result, '\n') or nil
    end
    logs(getFunc(self.rootNode))
end


return RedPointMgrComponent
